/*
 * The way a record goes through its steps (DS-07 node progress). Pure data:
 * the UI turns each step into a node with its label, icon, date and hint.
 */

export type StepState = "done" | "current" | "late" | "todo" | "stopped"

export interface RecordStep<K extends string = string> {
  key: K
  state: StepState
  /** When the step happened (ISO date or timestamp) or, for a step ahead, when it is due */
  at?: string
  /** Days past the date the waiting step was due */
  lateDays?: number
  /** Days left before a waiting step runs out */
  daysLeft?: number
  /** How far the line into this step is filled, 0–1, when it is not simply done or waiting */
  reach?: number
  /** Money received so far toward this step (part payments) */
  paid?: number
  total?: number
}

const day = (iso?: string) => iso?.slice(0, 10)

// Creation steps (draft, asked) carry no date: the record's own dates say more
// than when someone first opened the form.

export type InvoiceStepKey = "draft" | "issued" | "sent" | "paid" | "cancelled"

/** Draft → issued → sent → paid; the line into "paid" fills with the share already paid. */
export function invoiceWay(invoice: ClientInvoice, today = todayIso()): RecordStep<InvoiceStepKey>[] {
  const issuedAt = invoice.issuedAt ?? invoice.issueDate
  if (invoice.status === ClientInvoiceStatus.VOID) {
    return [
      { key: "draft", state: "done" },
      { key: "issued", state: "done", at: issuedAt },
      { key: "cancelled", state: "stopped", at: invoice.updatedAt },
    ]
  }
  const order: InvoiceStepKey[] = ["draft", "issued", "sent", "paid"]
  const reached = order.indexOf(invoice.status as InvoiceStepKey)
  const payments = invoice.payments ?? []
  const lastPayment = payments.map((p) => p.date).sort().at(-1)
  const at: Record<InvoiceStepKey, string | undefined> = {
    draft: undefined,
    issued: invoice.status === ClientInvoiceStatus.DRAFT ? undefined : issuedAt,
    sent: invoice.sentAt,
    paid: invoice.paidAt ?? (invoice.status === ClientInvoiceStatus.PAID ? lastPayment : undefined),
    cancelled: undefined,
  }
  const late = invoice.status !== ClientInvoiceStatus.DRAFT && invoice.status !== ClientInvoiceStatus.PAID && invoice.dueDate < today
  return order.map((key, i) => {
    if (i <= reached && !(invoice.status === ClientInvoiceStatus.DRAFT && key === "draft")) return { key, state: "done", at: at[key] }
    const waiting = invoice.status === ClientInvoiceStatus.DRAFT ? i === 0 : i === reached + 1
    if (!waiting) return { key, state: "todo", at: key === "paid" ? invoice.dueDate : undefined }
    const step: RecordStep<InvoiceStepKey> = { key, state: late ? "late" : "current", at: key === "draft" ? at.draft : key === "paid" ? invoice.dueDate : undefined }
    if (late) step.lateDays = daysBetween(invoice.dueDate, today)
    if (key === "paid" && payments.length > 0) {
      const total = invoiceTotals(invoice).total
      const paid = payments.reduce((s, p) => s + p.amount, 0)
      step.paid = paid
      step.total = total
      step.reach = total > 0 ? Math.min(1, paid / total) : 0.5
    }
    return step
  })
}

export type QuoteStepKey = "draft" | "sent" | "accepted" | "invoiced" | "declined" | "expired"

/** Draft → sent → accepted → invoiced; declined or expired stops the way. */
export function quoteWay(quote: Quote, status: QuoteDisplayStatus, today = todayIso(), invoicedAt?: string): RecordStep<QuoteStepKey>[] {
  const draft: RecordStep<QuoteStepKey> = { key: "draft", state: status === QuoteStatus.DRAFT ? "current" : "done" }
  if (status === QuoteStatus.DRAFT) {
    return [draft, { key: "sent", state: "todo" }, { key: "accepted", state: "todo", at: quote.validUntil }, { key: "invoiced", state: "todo" }]
  }
  const sent: RecordStep<QuoteStepKey> = { key: "sent", state: "done", at: quote.sentAt ?? quote.issueDate }
  if (status === QuoteStatus.DECLINED) return [draft, sent, { key: "declined", state: "stopped", at: quote.decidedAt }]
  if (status === "expired") return [draft, sent, { key: "expired", state: "stopped", at: quote.validUntil }]
  if (status === QuoteStatus.SENT) {
    return [
      draft,
      sent,
      { key: "accepted", state: "current", at: quote.validUntil, daysLeft: Math.max(0, daysBetween(today, quote.validUntil)) },
      { key: "invoiced", state: "todo" },
    ]
  }
  const accepted: RecordStep<QuoteStepKey> = { key: "accepted", state: "done", at: quote.decidedAt }
  if (status === QuoteStatus.ACCEPTED) return [draft, sent, accepted, { key: "invoiced", state: "current" }]
  return [draft, sent, accepted, { key: "invoiced", state: "done", at: invoicedAt }]
}

export interface MilestoneStep extends RecordStep<string> {
  milestone: Milestone
  awaitingClient?: boolean
}

/**
 * A project's milestones in date order: reached ones are done, one waiting on
 * the client or the next one due is current, overdue ones are late.
 */
export function milestoneWay(milestones: Milestone[], tasks: WorkTask[], today = todayIso()): MilestoneStep[] {
  let currentGiven = false
  return [...milestones]
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate))
    .map((m) => {
      const s = milestoneState(m, tasks, today)
      if (s === MilestoneState.REACHED) return { key: m.id, milestone: m, state: "done", at: day(m.approvedAt) ?? m.dueDate }
      if (s === MilestoneState.OVERDUE) {
        currentGiven = true
        return { key: m.id, milestone: m, state: "late", at: m.dueDate, lateDays: daysBetween(m.dueDate, today) }
      }
      if (s === MilestoneState.AWAITING_APPROVAL) {
        currentGiven = true
        return { key: m.id, milestone: m, state: "current", at: m.dueDate, awaitingClient: true }
      }
      const first = !currentGiven
      currentGiven = true
      return first
        ? { key: m.id, milestone: m, state: "current", at: m.dueDate, daysLeft: Math.max(0, daysBetween(today, m.dueDate)) }
        : { key: m.id, milestone: m, state: "todo", at: m.dueDate }
    })
}

export type LeaveStepKey = "asked" | "firstApproval" | "approved" | "rejected" | "cancelled"

/** Asked → (first approval when the workspace needs two) → approved, or stopped. */
export function leaveWay(request: LeaveRequest, steps: number): RecordStep<LeaveStepKey>[] {
  const asked: RecordStep<LeaveStepKey> = { key: "asked", state: "done" }
  const two = steps >= 2
  const first: RecordStep<LeaveStepKey>[] = two
    ? [{ key: "firstApproval", state: request.firstApprovedBy || request.status === LeaveStatus.APPROVED ? "done" : request.status === LeaveStatus.PENDING ? "current" : "todo" }]
    : []
  if (request.status === LeaveStatus.REJECTED) return [asked, ...first, { key: "rejected", state: "stopped", at: request.updatedAt }]
  if (request.status === LeaveStatus.CANCELLED) return [asked, ...first, { key: "cancelled", state: "stopped", at: request.updatedAt }]
  if (request.status === LeaveStatus.APPROVED) return [asked, ...first, { key: "approved", state: "done", at: request.updatedAt }]
  const waitingFinal = !two || !!request.firstApprovedBy
  return [asked, ...first, { key: "approved", state: waitingFinal ? "current" : "todo" }]
}

export type ExpenseStepKey = "submitted" | "firstApproval" | "approved" | "reimbursed" | "rejected"

/** Submitted → (first approval when two are needed) → approved → paid back; a refusal stops the way. */
export function expenseWay(expense: Expense, steps: number): RecordStep<ExpenseStepKey>[] {
  const submitted: RecordStep<ExpenseStepKey> = { key: "submitted", state: "done", at: expense.date }
  const two = steps >= 2
  const passed = expense.status === ExpenseStatus.APPROVED || expense.status === ExpenseStatus.REIMBURSED
  const first: RecordStep<ExpenseStepKey>[] = two
    ? [{ key: "firstApproval", state: expense.firstApprovedBy || passed ? "done" : expense.status === ExpenseStatus.SUBMITTED ? "current" : "todo" }]
    : []
  if (expense.status === ExpenseStatus.REJECTED) return [submitted, ...first, { key: "rejected", state: "stopped", at: expense.updatedAt }]
  if (expense.status === ExpenseStatus.REIMBURSED) return [submitted, ...first, { key: "approved", state: "done" }, { key: "reimbursed", state: "done", at: expense.updatedAt }]
  if (expense.status === ExpenseStatus.APPROVED) return [submitted, ...first, { key: "approved", state: "done", at: expense.updatedAt }, { key: "reimbursed", state: "current" }]
  const waitingFinal = !two || !!expense.firstApprovedBy
  return [submitted, ...first, { key: "approved", state: waitingFinal ? "current" : "todo" }, { key: "reimbursed", state: "todo" }]
}

export type BillStepKey = "entered" | "approved" | "paid" | "rejected"

/** Entered → approved → paid; the line into "paid" fills with what is already paid, late past the due date. */
export function billWay(bill: SupplierBill, today = todayIso()): RecordStep<BillStepKey>[] {
  const entered: RecordStep<BillStepKey> = { key: "entered", state: "done", at: bill.issueDate }
  if (bill.status === SupplierBillStatus.REJECTED) return [entered, { key: "rejected", state: "stopped", at: bill.updatedAt }]
  if (bill.status === SupplierBillStatus.SUBMITTED) return [entered, { key: "approved", state: "current" }, { key: "paid", state: "todo", at: bill.dueDate }]
  const approved: RecordStep<BillStepKey> = { key: "approved", state: "done" }
  const lastPayment = bill.payments.map((p) => p.date).sort().at(-1)
  if (bill.status === SupplierBillStatus.PAID) return [entered, approved, { key: "paid", state: "done", at: lastPayment ?? bill.updatedAt }]
  const late = bill.dueDate < today
  const paid: RecordStep<BillStepKey> = { key: "paid", state: late ? "late" : "current", at: bill.dueDate }
  if (late) paid.lateDays = daysBetween(bill.dueDate, today)
  else paid.daysLeft = Math.max(0, daysBetween(today, bill.dueDate))
  if (bill.payments.length > 0) {
    const { total, paid: sum } = billTotals(bill)
    paid.paid = sum
    paid.total = total
    paid.reach = total > 0 ? Math.min(1, sum / total) : 0.5
  }
  return [entered, approved, paid]
}

export type TimesheetStepKey = "submitted" | "firstApproval" | "approved" | "invoiced"

/** A person's week of hours: submitted → (first approval) → approved → on an invoice, as far as every entry got. */
export function timesheetWay(entries: TimeEntry[], steps: number): RecordStep<TimesheetStepKey>[] {
  const all = (ok: (e: TimeEntry) => boolean) => entries.length > 0 && entries.every(ok)
  const approved = all((e) => e.status === TimeEntryStatus.APPROVED)
  const invoiced = approved && all((e) => !!e.invoiceId)
  const submitted = approved || all((e) => e.status === TimeEntryStatus.SUBMITTED || e.status === TimeEntryStatus.APPROVED)
  const two = steps >= 2
  const firstDone = approved || all((e) => !!e.firstApprovedBy)
  const lastApproval = entries.map((e) => e.approvedAt).filter((x): x is string => !!x).sort().at(-1)
  const out: RecordStep<TimesheetStepKey>[] = [{ key: "submitted", state: submitted ? "done" : "current" }]
  if (two) out.push({ key: "firstApproval", state: firstDone ? "done" : submitted ? "current" : "todo" })
  out.push({ key: "approved", state: approved ? "done" : submitted && (!two || firstDone) ? "current" : "todo", at: approved ? lastApproval : undefined })
  out.push({ key: "invoiced", state: invoiced ? "done" : approved ? "current" : "todo" })
  return out
}
